frappe.ui.form.on('Quotation Item Escalated', {
    quantity_range: function(frm, cdt, cdn) {
        set_quantity_limits(frm, cdt, cdn);
        calculate_prices(frm, cdt, cdn);
    },
    
    ex_works_price: function(frm, cdt, cdn) {
        calculate_prices(frm, cdt, cdn);
    },
    
    freight_cost: function(frm, cdt, cdn) {
        calculate_prices(frm, cdt, cdn);
    },
    
    freight_type: function(frm, cdt, cdn) {
        calculate_freight_based_on_type(frm, cdt, cdn);
    }
});

function set_quantity_limits(frm, cdt, cdn) {
    var row = frappe.get_doc(cdt, cdn);
    
    switch(row.quantity_range) {
        case '1-5 kg':
            row.min_quantity = 1;
            row.max_quantity = 5;
            break;
        case '6-10 kg':
            row.min_quantity = 6;
            row.max_quantity = 10;
            break;
        case '11-25 kg':
            row.min_quantity = 11;
            row.max_quantity = 25;
            break;
        case '26-200 kg':
            row.min_quantity = 26;
            row.max_quantity = 200;
            break;
        default:
            row.min_quantity = 0;
            row.max_quantity = 0;
    }
    
    frappe.model.set_value(cdt, cdn, 'min_quantity', row.min_quantity);
    frappe.model.set_value(cdt, cdn, 'max_quantity', row.max_quantity);
}

function calculate_freight_based_on_type(frm, cdt, cdn) {
    var row = frappe.get_doc(cdt, cdn);
    var freight_cost = 0;
    
    // Set freight cost based on quantity range and freight type
    if (row.quantity_range && row.freight_type) {
        switch(row.quantity_range) {
            case '1-5 kg':
                freight_cost = (row.freight_type === 'Air Freight') ? 58.30 : 
                              (row.freight_type === 'Sea Freight') ? 45.00 :
                              (row.freight_type === 'Ground') ? 35.00 : 60.00;
                break;
            case '6-10 kg':
                freight_cost = (row.freight_type === 'Air Freight') ? 19.87 : 
                              (row.freight_type === 'Sea Freight') ? 15.00 :
                              (row.freight_type === 'Ground') ? 12.00 : 22.00;
                break;
            case '11-25 kg':
                freight_cost = (row.freight_type === 'Air Freight') ? 16.06 : 
                              (row.freight_type === 'Sea Freight') ? 12.00 :
                              (row.freight_type === 'Ground') ? 9.00 : 18.00;
                break;
            case '26-200 kg':
                freight_cost = (row.freight_type === 'Air Freight') ? 13.91 : 
                              (row.freight_type === 'Sea Freight') ? 10.00 :
                              (row.freight_type === 'Ground') ? 7.00 : 15.00;
                break;
        }
        
        frappe.model.set_value(cdt, cdn, 'freight_cost', freight_cost);
        calculate_prices(frm, cdt, cdn);
    }
}

function calculate_prices(frm, cdt, cdn) {
    var row = frappe.get_doc(cdt, cdn);
    
    if (row.ex_works_price && row.freight_cost && row.min_quantity && row.max_quantity) {
        // Calculate delivered price per kg
        var delivered_price = flt(row.ex_works_price) + flt(row.freight_cost);
        frappe.model.set_value(cdt, cdn, 'delivered_price', delivered_price);
        
        // Calculate price per kg
        frappe.model.set_value(cdt, cdn, 'price_per_kg', delivered_price);
        
        // Calculate total price range (min and max)
        var min_total = delivered_price * row.min_quantity;
        var max_total = delivered_price * row.max_quantity;
        
        // Display as range or single value
        if (row.min_quantity === row.max_quantity) {
            frappe.model.set_value(cdt, cdn, 'total_price', min_total);
        } else {
            frappe.model.set_value(cdt, cdn, 'total_price', max_total);
            // You could also display as range: min_total + " - " + max_total
        }
    }
}

/**
 * QUOTATION ITEM ESCALATED - FIXED CLIENT SCRIPT
 * 
 * Purpose: Auto-calculate freight costs and delivered prices for items
 *          in the Quotation Item Escalated child table
 * 
 * Fixes Applied:
 * 1. Added triggers for child table events (qty, item_code)
 * 2. Fetches shipping rate from parent quotation's shipping rule
 * 3. Calculates freight_cost based on tiered pricing
 * 4. Calculates delivered_price = ex_works_price + freight_cost
 * 5. Proper promise error handling
 * 
 * Date: 2025-10-18
 * Environment: Test -> Production
 */

// ============================================================================
// CHILD TABLE EVENT HANDLERS
// ============================================================================

frappe.ui.form.on('Quotation Item Escalated', {

    // When item is selected
    item_code: function(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        console.log('✅ Item selected:', row.item_code);

        if (row.item_code) {
            // Fetch item price
            fetch_item_price(frm, cdt, cdn);

            // Calculate freight if qty is available
            if (row.qty && row.qty > 0) {
                calculate_freight_and_delivered_price(frm, cdt, cdn);
            }
        }
    },

    // When quantity changes
    qty: function(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        console.log('✅ Quantity changed:', row.qty);

        if (row.qty && row.qty > 0 && row.item_code) {
            calculate_freight_and_delivered_price(frm, cdt, cdn);
        }
    },

    // When ex_works_price changes (manual or fetched)
    ex_works_price: function(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        console.log('✅ Ex-works price changed:', row.ex_works_price);

        if (row.qty && row.qty > 0) {
            calculate_delivered_price(frm, cdt, cdn);
        }
    },

    // When freight_cost changes (manual override allowed)
    freight_cost: function(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        console.log('✅ Freight cost changed:', row.freight_cost);
        calculate_delivered_price(frm, cdt, cdn);
    }
});

// ============================================================================
// HELPER FUNCTIONS
// ============================================================================

/**
 * Fetch item price from Item master
 */
function fetch_item_price(frm, cdt, cdn) {
    const row = locals[cdt][cdn];

    frappe.call({
        method: 'frappe.client.get',
        args: {
            doctype: 'Item',
            name: row.item_code
        },
        callback: function(r) {
            if (r.message) {
                const item = r.message;
                const ex_works_price = item.standard_rate || item.valuation_rate || 0;

                console.log(`✅ Fetched ex-works price for ${row.item_code}: $${ex_works_price}`);

                frappe.model.set_value(cdt, cdn, 'ex_works_price', ex_works_price)
                    .catch(err => console.error('❌ Error setting ex_works_price:', err));
            }
        },
        error: function(err) {
            console.error('❌ Error fetching item:', err);
            frappe.msgprint(__('Could not fetch item details'));
        }
    });
}

/**
 * Calculate freight cost based on shipping rule and quantity
 */
function calculate_freight_and_delivered_price(frm, cdt, cdn) {
    const row = locals[cdt][cdn];
    const shipping_rule = frm.doc.shipping_rule;

    if (!shipping_rule) {
        console.warn('⚠️ No shipping rule selected on quotation');
        frappe.msgprint(__('Please select a Shipping Rule on the quotation first'));
        return;
    }

    if (!row.qty || row.qty <= 0) {
        console.warn('⚠️ Invalid quantity');
        return;
    }

    console.log(`🔍 Fetching shipping rate for: ${shipping_rule}, Qty: ${row.qty} kg`);

    // Fetch shipping rule details
    frappe.call({
        method: 'frappe.client.get',
        args: {
            doctype: 'Shipping Rule',
            name: shipping_rule
        },
        callback: function(r) {
            if (r.message && r.message.conditions) {
                const conditions = r.message.conditions;
                const qty = parseFloat(row.qty);

                // Find the matching tier
                let shipping_rate = 0;
                for (let condition of conditions) {
                    const from_val = parseFloat(condition.from_value);
                    const to_val = parseFloat(condition.to_value);
                    const rate = parseFloat(condition.shipping_amount);

                    if (qty > from_val && qty <= to_val) {
                        shipping_rate = rate;
                        console.log(`✅ Matched tier: ${from_val}-${to_val} kg = $${rate}/kg`);
                        break;
                    }
                }

                // Calculate freight cost
                const freight_cost = shipping_rate * qty;
                console.log(`✅ Calculated freight cost: $${shipping_rate}/kg × ${qty} kg = $${freight_cost}`);

                // Set freight_cost field
                frappe.model.set_value(cdt, cdn, 'freight_cost', freight_cost)
                    .then(() => {
                        // Also set freight location and type if available
                        if (r.message.custom_applicable_country) {
                            frappe.model.set_value(cdt, cdn, 'freight_location', r.message.custom_applicable_country)
                                .catch(err => console.error('❌ Error setting freight_location:', err));
                        }
                    })
                    .catch(err => console.error('❌ Error setting freight_cost:', err));

            } else {
                console.error('❌ No conditions found in shipping rule');
                frappe.msgprint(__('Shipping rule has no rate conditions defined'));
            }
        },
        error: function(err) {
            console.error('❌ Error fetching shipping rule:', err);
            frappe.msgprint(__('Could not fetch shipping rule details'));
        }
    });
}

/**
 * Calculate delivered price = ex_works_price + freight_cost
 */
function calculate_delivered_price(frm, cdt, cdn) {
    const row = locals[cdt][cdn];

    const ex_works = parseFloat(row.ex_works_price) || 0;
    const freight = parseFloat(row.freight_cost) || 0;
    const delivered = ex_works + freight;

    console.log(`✅ Calculating delivered price: $${ex_works} + $${freight} = $${delivered}`);

    frappe.model.set_value(cdt, cdn, 'delivered_price', delivered)
        .catch(err => console.error('❌ Error setting delivered_price:', err));
}

// ============================================================================
// PARENT QUOTATION EVENT HANDLERS
// ============================================================================

frappe.ui.form.on('Quotation', {

    // When shipping rule changes on parent quotation
    shipping_rule: function(frm) {
        console.log('✅ Shipping rule changed on quotation:', frm.doc.shipping_rule);

        // Recalculate all items in the escalated table
        if (frm.doc.custom_quotation_child_table && frm.doc.custom_quotation_child_table.length > 0) {
            frm.doc.custom_quotation_child_table.forEach(row => {
                if (row.qty && row.qty > 0 && row.item_code) {
                    const cdt = row.doctype;
                    const cdn = row.name;
                    calculate_freight_and_delivered_price(frm, cdt, cdn);
                }
            });
        }
    },

    // Optional: Refresh button to recalculate all
    refresh: function(frm) {
        if (frm.doc.custom_quotation_child_table && frm.doc.custom_quotation_child_table.length > 0) {
            frm.add_custom_button(__('Recalculate All Freight'), function() {
                frm.doc.custom_quotation_child_table.forEach(row => {
                    if (row.qty && row.qty > 0 && row.item_code) {
                        const cdt = row.doctype;
                        const cdn = row.name;
                        calculate_freight_and_delivered_price(frm, cdt, cdn);
                    }
                });
                frappe.msgprint(__('Recalculation triggered for all items'));
            });
        }
    }
});

console.log('✅ QUOTATION ITEM ESCALATED AUTOMATION LOADED (v5.0 - Fixed)');
